        button.innerHTML = '<svg aria-hidden="true" width="13" height="13" viewBox="0 0 24 24" fill="none"><path d="M4 4v6h6M5.5 15a7 7 0 1 0 1-8.5L4 10" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
        input.addEventListener("input", () => {
          apply(input.value)
          onUpdate()
        })
